// ============================== SERVICE WORKER ==============================
// Generated by tools/build.py. Keeps the game playable offline. A new release changes the
// build stamp below, the browser installs the new files quietly, and the game offers
// "Update ready, tap to refresh" when the player isn't in the middle of a game.
const BUILD = "1.0.0-85bdde2091";
const CACHE = "lamb-stampede-" + BUILD;
const FILES = [
 "./",
 "css/app.css",
 "fonts/OFL.txt",
 "fonts/fredoka.woff2",
 "icons/apple-touch-icon.png",
 "icons/favicon.png",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/maskable-512.png",
 "img/og.jpg",
 "index.html",
 "js/app.js",
 "js/art.js",
 "js/audio.js",
 "js/base.js",
 "js/config.js",
 "js/core.js",
 "js/engine.js",
 "js/licences.js",
 "js/modes/flockfall.js",
 "js/modes/lostlamb.js",
 "js/modes/rush.js",
 "js/modes/saga.js",
 "js/modes/stampede.js",
 "js/modes/wolf.js",
 "js/progress.js",
 "js/pwa.js",
 "js/screens.js",
 "js/share.js",
 "js/strings.js",
 "js/ui.js",
 "manifest.webmanifest",
 "privacy.html"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: "reload" })))));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith("lamb-stampede-") && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener("message", (e) => {
  if (e.data === "skipWaiting") self.skipWaiting();
});

// cache first (it's all ours and versioned by BUILD); pages fall back to the game when offline
self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== location.origin) return;
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).catch(() => (req.mode === "navigate" ? caches.match("./") : Response.error())))
  );
});
